// src/lib/Counter.svelte
<script>
	let count = $state(0);

	function increment() {
		count++;
	}

	function decrement() {
		count--;
	}
</script>

<div class="counter">
	<button data-testid="decrement-button" onclick={decrement}>-</button>
	<span data-testid="count-value" class="count">{count}</span>
	<button data-testid="increment-button" onclick={increment}>+</button>
</div>

<style>
	.counter {
		display: flex;
		align-items: center;
		gap: 0.5rem;
		padding: 0.5rem;
		border: 1px solid #ccc;
		border-radius: 4px;
	}

	.count {
		min-width: 2rem;
		text-align: center;
	}
</style>

