<script>
	let text = $state('');

	let { wordCount, charCount, isLong } = $derived.by(() => {
		const words = text.trim().split(/\s+/).filter(Boolean).length;
		const chars = text.length;
		const isLong = words > 15;
		return { wordCount: words, charCount: chars, isLong };
	});

	function clearText() {
		text = '';
	}
</script>

<div>
  <input
    data-testid="text-input"
    type="text"
    bind:value={text}
    placeholder="Enter some text..."
  />
  <button
    data-testid="clear-button"
    onclick={clearText}
  >
    Clear
  </button>
  <div>
    <p data-testid="word-count">Words: {wordCount}</p>
    <p data-testid="char-count">Characters: {charCount}</p>
    <p data-testid="length-indicator">
      Status: {isLong ? 'Long text' : 'Short text'}
    </p>
  </div>
</div>

