<script>
	let text = $state('Hello world');

	// Basic inspection
	$inspect(text);

	// Custom inspection with callback
	$inspect(text).with((v) => {
		console.log('Text updated to:', v);
	});

	// Trace inspection for debugging
	$inspect.trace();

	// Derived character count
	let charCount = $derived(text.length);
</script>

<div>
	<input
		data-testid="text-input"
		type="text"
		bind:value={text}
	/>
	<p data-testid="text-value">Current text: "{text}"</p>
	<p data-testid="char-count">Character count: {charCount}</p>
</div>

