<script>
	let { name = 'World', count = 0, showDetails = false } = $props();

	let localCount = count;

	function increment() {
		localCount++;
	}

	let localName = name;

	$effect(() => {
		console.log(`Props updated: name=${localName}, count=${localCount}`);
	});
</script>

<div>
  <h1 data-testid="name-display">{localName}</h1>
  <p data-testid="count-display">Count: {localCount}</p>
  <button data-testid="increment-button" onclick={increment}>Increment</button>

  {#if showDetails}
    <div data-testid="details">
      <p>Name is {localName}</p>
      <p>Count is {localCount}</p>
      <p>ShowDetails is {showDetails ? 'true' : 'false'}</p>
    </div>
  {/if}
</div>
